(function(){
"use strict";
const state={ws:null,values:{1:null,2:null},root:null,layer:null,panel:null,drag:null};
const css=`.pmr-marker-layer{position:absolute;inset:0;z-index:30;pointer-events:none;overflow:visible}.pmr-marker-line{position:absolute;top:0;bottom:0;width:2px;background:#ffd18a;box-shadow:0 0 2px #111;pointer-events:auto;touch-action:none;cursor:ew-resize}.pmr-marker-label{position:absolute;top:2px;left:1px;transform:translateX(-50%);min-width:20px;height:20px;padding:0 4px;border-radius:4px;background:#ffd18a;color:#242424;font:600 12px/20px Arial,sans-serif;text-align:center;box-shadow:0 1px 4px #0008;user-select:none}.pmr-marker-panel{position:absolute;right:6px;top:5px;z-index:35;display:flex;gap:5px;flex-wrap:wrap;max-width:calc(100% - 12px);pointer-events:auto}.pmr-marker-row{display:flex;align-items:center;gap:4px;padding:3px 5px;background:#20252b;color:#eee;border:1px solid #59616a;border-radius:5px;font:12px Arial,sans-serif}.pmr-marker-row b{color:#ffd18a}.pmr-marker-time{width:94px;min-width:0;padding:3px 4px;border:1px solid #606873;border-radius:3px;background:#111820;color:#fff;font:12px monospace}.pmr-marker-remove{border:0;background:transparent;color:#bbb;font-size:16px;line-height:18px;padding:0 2px;cursor:pointer}@media(max-width:600px){.pmr-marker-time{width:88px}.pmr-marker-panel{left:4px;right:4px;top:4px;justify-content:flex-end}}`;
function style(){if(document.getElementById("pmr-marker-style"))return;let e=document.createElement("style");e.id="pmr-marker-style";e.textContent=css;document.head.appendChild(e)}
function fmt(v){v=Math.max(0,Number(v)||0);let h=Math.floor(v/3600),m=Math.floor(v%3600/60),s=Math.floor(v%60),ms=Math.floor((v-Math.floor(v))*1000),z=n=>String(n).padStart(2,"0");return(h?z(h)+":":"")+z(m)+":"+z(s)+"."+String(ms).padStart(3,"0")}
function parse(v){v=String(v||"").trim().replace(",",".");if(/^\d+(\.\d+)?$/.test(v))return Number(v);let p=v.split(":");if(p.length<2||p.length>3)return NaN;let s=Number(p.pop()),m=Number(p.pop()),h=p.length?Number(p.pop()):0;if(![s,m,h].every(Number.isFinite)||s>=60||m>=60)return NaN;return h*3600+m*60+s}
function dur(){return state.ws&&Number(state.ws.getDuration())||0}
function ensure(){let r=document.querySelector(".pk_av");if(!r)return false;if(state.root===r)return true;state.root=r;r.style.position=r.style.position||"relative";state.layer=document.createElement("div");state.layer.className="pmr-marker-layer";r.appendChild(state.layer);state.panel=document.createElement("div");state.panel.className="pmr-marker-panel";r.appendChild(state.panel);return true}
function draw(){if(!ensure())return;let d=dur(),ws=state.ws;state.layer.replaceChildren();state.panel.replaceChildren();for(let id of [1,2]){let val=state.values[id];if(val===null||!d)continue;let vis=Number(ws.VisibleDuration)||d,left=Number(ws.LeftProgress)||0,p=(val-left)/vis*100;if(p<0||p>100)continue;let line=document.createElement("div");line.className="pmr-marker-line";line.style.left=p+"%";line.dataset.marker=id;let lab=document.createElement("span");lab.className="pmr-marker-label";lab.textContent=id;line.appendChild(lab);line.addEventListener("pointerdown",e=>{e.preventDefault();state.drag=id});state.layer.appendChild(line);let row=document.createElement("div");row.className="pmr-marker-row";let b=document.createElement("b");b.textContent=id;row.appendChild(b);let input=document.createElement("input");input.className="pmr-marker-time";input.type="text";input.inputMode="decimal";input.setAttribute("aria-label","Время маркера "+id);input.value=fmt(val);let apply=()=>{let n=parse(input.value);if(Number.isFinite(n)&&n>=0&&n<=d){state.values[id]=n;draw()}else input.value=fmt(state.values[id])};input.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();apply();input.blur()}});input.addEventListener("blur",apply);row.appendChild(input);let rm=document.createElement("button");rm.type="button";rm.className="pmr-marker-remove";rm.textContent="×";rm.title="Удалить маркер";rm.addEventListener("click",()=>{state.values[id]=null;draw()});row.appendChild(rm);state.panel.appendChild(row)}}
function set(id,ws){if(!ws||typeof ws.getCurrentTime!=="function")return;state.ws=ws;ensure();state.values[id]=Math.max(0,Math.min(dur(),ws.getCurrentTime()));draw()}
function refresh(){if(state.ws)draw()}
function clear(){state.values={1:null,2:null};draw()}
function move(x){if(!state.drag||!state.ws||!state.root)return;let r=state.root.getBoundingClientRect(),ws=state.ws,d=dur();if(!r.width||!d)return;state.values[state.drag]=Math.max(0,Math.min(d,(Number(ws.LeftProgress)||0)+(x-r.left)/r.width*(Number(ws.VisibleDuration)||d)));draw()}
document.addEventListener("pointermove",e=>move(e.clientX));document.addEventListener("pointerup",()=>{state.drag=null});window.addEventListener("resize",refresh);style();let ob=new MutationObserver(()=>{if(ensure())draw()});ob.observe(document.body,{childList:true,subtree:true});window.PMRMarkers={set,refresh,clear};
})();